import sys
from collections import Counter
from math import factorial

MOD = 10**9 + 9

def count_unsorted_permutations(n, arr):
    def is_sorted(arr):
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1)) or all(arr[i] >= arr[i + 1] for i in range(len(arr) - 1))

    def count_permutations_with_fixed_points(arr):
        count = Counter(arr)
        total_permutations = factorial(len(arr)) % MOD
        for freq in count.values():
            total_permutations *= pow(factorial(freq), MOD - 2, MOD)
            total_permutations %= MOD
        return total_permutations

    def count_entirely_unsorted_permutations(arr):
        total_permutations = count_permutations_with_fixed_points(arr)
        sorted_permutations = 0
        for i in range(1, len(arr)):
            for j in range(i + 1, len(arr) + 1):
                subarray = arr[i:j]
                if is_sorted(subarray):
                    sorted_permutations += count_permutations_with_fixed_points(subarray)
                    sorted_permutations %= MOD
        return (total_permutations - sorted_permutations + MOD) % MOD

    return count_entirely_unsorted_permutations(arr)

