MOD = 10**9 + 9

def factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = result * i % mod
    return result

def inverse_factorial(n, mod):
    return pow(factorial(n, mod), mod - 2, mod)

def count_unsorted_permutations(n, a):
    freq = {}
    for num in a:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    total_permutations = factorial(n, MOD)

    for count in freq.values():
        total_permutations = total_permutations * inverse_factorial(count, MOD) % MOD

    sorted_positions = 0
    for i in range(1, n - 1):
        if a[i - 1] <= a[i] <= a[i + 1]:
            sorted_positions += 1

    if a[0] <= a[1]:
        sorted_positions += 1

    if a[n - 2] <= a[n - 1]:
        sorted_positions += 1

    unsorted_permutations = total_permutations - sorted_positions
    if unsorted_permutations < 0:
        unsorted_permutations += MOD

    return unsorted_permutations

